-- =============================================================================
-- SeedDemoCompetitionsFrogtech
--
-- Loads three demonstration competitions into the platform organization
-- (slug 'frogtech-solutions', created by SeedPlatformOwner), with everything
-- that hangs from them:
--
--   Copa Vóley Frogtech 2026, Liga Básquet Frogtech 2026 and
--   Copa RoroPiRoro Taekwondo.
--
-- Rulesets, venue, clubs, athletes, categories, teams, rosters, matches and
-- player events. Test data, taken from a development database.
--
-- Deliberately left out:
--   * Every picture: club logos and athlete photos are NULL, and the
--     taekwondo portal settings lose their logo, sponsor logos and gallery
--     (those keys pointed into object storage that does not exist here).
--   * Users: matches.modified_by is NULL, and matches.recorded_by (required
--     by ck_result_completeness for every finished match) is the organization's
--     first member, the platform owner created by SeedPlatformOwner.
--   * Issued documents and document batches: they depend on templates, users
--     and stored files.
--
-- Ids are kept, so the migration is safe to re-run: every INSERT is
-- ON CONFLICT DO NOTHING, and the whole block is skipped when the
-- competitions are already there. player_events.metric_id is looked up by
-- (sport_code, code) because sport_metrics ids are not stable across
-- databases.
--
-- Does nothing if the organization does not exist. organization-scoped
-- tables are under FORCE ROW LEVEL SECURITY, so app.current_org is set to
-- the organization before anything is inserted.
-- =============================================================================

DO $$
DECLARE
    v_org uuid;
    v_user uuid;
BEGIN
    SELECT id INTO v_org FROM organizations WHERE slug = 'frogtech-solutions';

    IF v_org IS NULL THEN
        RETURN;
    END IF;

    PERFORM set_config('app.current_org', v_org::text, true);

    SELECT user_id INTO v_user
    FROM organization_memberships
    WHERE org_id = v_org
    ORDER BY created_at
    LIMIT 1;

    -- Finished matches cannot be stored without somebody who recorded them.
    IF v_user IS NULL THEN
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1 FROM competitions
        WHERE id IN ('97997415-7e0e-4705-89e0-ce9d597f3856', '45708442-acb4-408d-8f2e-3a4e0d305a20', 'ece3af57-b4f6-465d-9460-41f8a567de6c')
    ) THEN
        RETURN;
    END IF;

    INSERT INTO venues
    SELECT r.*
    FROM jsonb_array_elements(
$j$[{"id": "577246a5-f019-41b8-905a-3f3fc21c321f", "name": "Complejo Deportivo Roblox", "address": "Av. Panamericana", "maps_url": "https://www.google.com/maps?q=-17.419493,-66.158216", "is_active": true, "created_at": "2026-09-22T20:25:21.196825+00:00", "updated_at": "2026-09-22T20:25:21.196825+00:00"}]$j$::jsonb) AS e,
         LATERAL jsonb_populate_record(NULL::venues, e || jsonb_build_object('org_id', v_org)) AS r
    ON CONFLICT DO NOTHING;

    INSERT INTO venue_spaces
    SELECT r.*
    FROM jsonb_array_elements(
$j$[{"id": "a27b5499-f471-438b-8a2c-205fb8f1fa8d", "name": "Tatami 1", "venue_id": "577246a5-f019-41b8-905a-3f3fc21c321f", "is_active": true, "created_at": "2026-09-22T20:25:42.321479+00:00", "updated_at": "2026-09-22T20:25:42.321479+00:00"}]$j$::jsonb) AS e,
         LATERAL jsonb_populate_record(NULL::venue_spaces, e || jsonb_build_object('org_id', v_org)) AS r
